window.DS3_CHUNK("rings",[{"id":"aldrichs-ruby","kind":"ring","name":"Aldrich's Ruby","page":"Aldrich's Ruby","img":"assets/img/Aldrich_s_Ruby.webp","effect":"Recovers 85 HP from critical attacks.","weight":0.8,"found":"Deep Accursed - drop","desc":"A malformed ring left by Aldrich, Saint of the Deep. Recovers HP from critical attacks.\nAldrich, infamous for his appetite for flesh, apparently had the desire to share with others his joy of imbibing the final shudders of life while luxuriating in his victim's screams.","avail":"<p>Dropped by the Deep Accursed found in <a data-e=\"anor-londo\">Anor Londo<\/a>'s cathedral.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Aldrich's_Ruby"},{"id":"aldrichs-sapphire","kind":"ring","name":"Aldrich's Sapphire","page":"Aldrich's Sapphire","img":"assets/img/Aldrich_s_Sapphire.webp","effect":"Recovers 15 FP from critical attacks.","weight":0.8,"found":"Deep Accursed - drop","desc":"A malformed ring left by Aldrich, Saint of the Deep. Recovers FP from critical attacks.\nAldrich, infamous for his appetite for flesh, apparently had the desire to share with others his joy of imbibing the final shudders of life while luxuriating in his victim's screams.","avail":"<p>Dropped by the Deep Accursed found in the room behind the first Cathedral Knight on the bottom-most floor of the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>, before the open area where the two giants are located.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Aldrich's_Sapphire"},{"id":"ashen-estus-ring","kind":"ring","name":"Ashen Estus Ring","page":"Ashen Estus Ring","img":"assets/img/Ashen_Estus_Ring.webp","effect":"Increases FP restored by Ashen Estus Flask by 20%.","weight":0.8,"found":"Untended Graves","desc":"Gray crystalline ring crafted from shards.\nIncreases FP restored by Ashen Estus Flask.\nOnce a treasure brought before Lothric's Queen, she had it enshrined in the Cemetery of Untended Graves, so that one day an Unkindled might profit from its use.","avail":"<p>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>. From the first bonfire, proceed onward and turn left on the first path. The ring is guarded by several Corvians and a Storyteller.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ashen_Estus_Ring"},{"id":"bellowing-dragoncrest-ring","kind":"ring","name":"Bellowing Dragoncrest Ring","page":"Bellowing Dragoncrest Ring (Dark Souls III)","img":"assets/img/Bellowing_Dragoncrest_Ring__Dark_Souls_III.webp","effect":"Boosts sorceries by 20%.","weight":1,"found":"Irithyll Dungeon","desc":"A special ring given to those who are deemed fit to undertake the journey of discovery in Vinheim, home of sorcery.\nGreatly boost sorceries.\nApropos to the Dragon School, the seal depicts an everlasting dragon. A bellowing dragon symbolizes the true nature of the consummate sorcerer.","avail":"<p>Found in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>. Requires the <a data-e=\"jailbreakers-key\">Jailbreaker's Key<\/a>.<\/p><p>Once the key has been procured, from the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a> bonfire, advance toward the main cell block area and turn right. Proceed straight ahead until reaching the end of the corridor on the upper floor and unlock the barred window at the end. The ring can be looted from a corpse lying on one of the rock ledges accessed afterward.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Bellowing_Dragoncrest_Ring_(Dark_Souls_III)"},{"id":"bloodbite-ring","kind":"ring","name":"Bloodbite Ring","page":"Bloodbite Ring (Dark Souls III)","img":"assets/img/Bloodbite_Ring__Dark_Souls_III.webp","effect":"Increases bleed resistance by 90.","weight":0.6,"found":"Undead Settlement","desc":"One of the bite rings native to Carim.\nIncreases bleed resistance.\nThe crafting of these rings is forbidden, perhaps owing to a fear of malleable stones.\nClerics, however, dabble freely in the art.","avail":"<ul><li><b>Bloodbite Ring<\/b><ul><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. Automatically acquired upon defeating the Giant Hound Rat lurking in the sewers.<\/li><\/ul><\/li><li><b>Bloodbite Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>, on a corpse lying to the right of the giant ballista.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Bloodbite_Ring_(Dark_Souls_III)"},{"id":"blue-tearstone-ring","kind":"ring","name":"Blue Tearstone Ring","page":"Blue Tearstone Ring (Dark Souls III)","img":"assets/img/Blue_Tearstone_Ring__Dark_Souls_III.webp","effect":"Boosts damage absorption by 20% when HP is below 20%.","weight":1.1,"found":"High Wall of Lothric (gift from Greirat)","desc":"A ring set with a large rare tearstone jewel.\nTemporarily boosts damage absorption when HP is low.\nThis stone is said to be a tear of sorrow of the goddess Caitha, and of course, tears are always more beautiful near death.","avail":"<p>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>. The ring is given to the player by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> after he has been freed from his cell and upon agreeing to help him (<a data-e=\"cell-key\">Cell Key<\/a> required).<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Blue_Tearstone_Ring_(Dark_Souls_III)"},{"id":"calamity-ring","kind":"ring","name":"Calamity Ring","page":"Calamity Ring (Dark Souls III)","img":"assets/img/Calamity_Ring__Dark_Souls_III.webp","effect":"Receive double damage.","weight":0.8,"found":"Archdragon Peak","desc":"A ring made from the orange eye of a calamitous dragon.\nReceive double damage.\nThis ring has no useful powers, and is merely a symbol of dragon worship, a thing quietly passed down amongst its most fervent adherents, some of whom become convinced the task has been bestowed upon them as a sacred duty.","avail":"<p>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>. Obtained by performing the &quot;Path of the Dragon&quot; gesture in front of the dragon statue at the <a data-e=\"archdragon-peak\">Dragon-Kin Mausoleum<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Calamity_Ring_(Dark_Souls_III)"},{"id":"carthus-bloodring","kind":"ring","name":"Carthus Bloodring","page":"Carthus Bloodring","img":"assets/img/Carthus_Bloodring.webp","effect":"Boosts rolling invincibility.","weight":0.8,"found":"Catacombs of Carthus","desc":"Ring worn by warriors of the sand kingdom, Carthus. Boosts rolling invincibility, at the cost of defense.\nThe sword technique of Carthus allows for fluid movement with a curved sword. Masters of the technique are said to dazzle their opponents by moving as weightlessly as a grain of sand.\nThey live for their High Lord Wolnir, conqueror of most kingdoms known to their people.","avail":"<p>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p><p>From the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a> bonfire, go downstairs and head right. Turn right at the corner and follow the long hallway inhabited by several Skeleton Wheels and Writhing Rotten Flesh to the end, where a corpse can be found holding the ring.<\/p>","notes":"<ul><li>Prior to the App 1.13 Regulation 1.33 patch, the Carthus Bloodring would reduce absorption by 15% rather than 30%.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Carthus_Bloodring"},{"id":"carthus-milkring","kind":"ring","name":"Carthus Milkring","page":"Carthus Milkring","img":"assets/img/Carthus_Milkring.webp","effect":"Boosts dexterity by 3 and obscures the wearer while rolling.","weight":0.8,"found":"Catacombs of Carthus","desc":"Ring worn by warriors of the sand kingdom, Carthus.\nSlightly boosts dexterity and obscures the wearer while rolling.\nThe sword technique of Carthus allows for fluid movement with a curved sword. Masters of the technique are said to dazzle their opponents by moving as weightlessly as a grain of sand.\nThey live for their High Lord Wolnir, conqueror of most kingdoms known to their people.","avail":"<p>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>, located at the end of an alley full of ancient urns after taking the large staircase with the first Skeleton Boulder.<\/p><p>Many of the urns surrounding the ring will release homing projectiles if broken. Additionally, a mage skeleton that throws the same type of projectiles guards the area and may break some unwanted urns with its own attacks. One of the urns is sitting on a pressure plate that will activate a trap of fire bolts if broken.<\/p><p>To easily claim the ring, start by disposing of the skeleton and then take a bow or any other kind of precise ranged attack. Identify the urn sitting on the pressure plate, shoot it from afar and use the nearby columns to take cover. The bolts shot by the trap will destroy most urns around the ring and all released projectiles will vanish once they hit a wall.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Carthus_Milkring"},{"id":"chillbite-ring","kind":"ring","name":"Chillbite Ring","page":"Chillbite Ring","img":"assets/img/Chillbite_Ring.webp","effect":"Increases frost resistance by 140 points.","weight":0.6,"found":"Painted World of Ariandel cathedral","desc":"One of the bite rings native to Carim. Increases frost resistance.\nThis ring would never grace Friede's hand, for the painting and its frost became her home.","avail":"<p><a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a>:<\/p><ul><li>Gifted by <a data-e=\"sister-friede\">Sister Friede<\/a> after speaking to her twice inside of <a data-e=\"painted-world-of-ariandel\">Ariandel Chapel<\/a>.<\/li><li>Dropped by Friede if her illusion within the chapel is attacked.<\/li><li>Left on Friede's chair if her boss fight is engaged without obtaining the ring from her.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Chillbite_Ring"},{"id":"chloranthy-ring","kind":"ring","name":"Chloranthy Ring","page":"Chloranthy Ring (Dark Souls III)","img":"assets/img/Chloranthy_Ring__Dark_Souls_III.webp","effect":"Raises stamina recovery speed by 7 points per second.","weight":0.7,"found":"Undead Settlement","desc":"This old ring is named for its decorative green blossom,\nbut its luster is long since faded.\nRaises stamina recovery speed.","avail":"<ul><li><b>Chloranthy Ring<\/b><ul><li>Found at the bottom of a tower in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. Jump off the lift that leads to the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a> while riding its upper part and onto a wooden scaffolding, then follow the only path available, fighting a Demon with <a data-e=\"siegward-of-catarina\">Siegward<\/a> along the way. Once reaching the rooftop of the next house, jump toward a nearby tower and enter it. Make way to the bottom and the ring can be found behind some wooden crates, near to the <a data-e=\"mirrah-set\">Mirrah Set<\/a>.<\/li><\/ul><\/li><li><b>Chloranthy Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, behind the pedestal that holds the <a data-e=\"ring-of-the-suns-first-born\">Ring of the Sun's First Born<\/a>.<\/li><\/ul><\/li><li><b>Chloranthy Ring+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>. Drop to a small ledge just to the left of the first Corvian Storyteller to find the ring.<\/li><\/ul><\/li><li><b>Chloranthy Ring+3 (<a data-e=\"the-ringed-city\">The Ringed City<\/a>)<\/b><ul><li>Found in <a data-e=\"the-ringed-city\">the Ringed City<\/a>, being held by the statue of Gwyn before the Church of Filianore. On the elevator that leads up to the Ringed Inner Wall bonfire, there is a secret path that eventually leads to a drop-down to the statue.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Chloranthy_Ring_(Dark_Souls_III)"},{"id":"covetous-gold-serpent-ring","kind":"ring","name":"Covetous Gold Serpent Ring","page":"Covetous Gold Serpent Ring (Dark Souls III)","img":"assets/img/Covetous_Gold_Serpent_Ring__Dark_Souls_III.webp","effect":"Increases item discovery by 50.","weight":1.2,"found":"Profaned Capital","desc":"A gold ring depicting a snake that could have been, but never was, a dragon.\nFallen foes are more likely to drop items.\nSnakes are known as creatures of great avarice, devouring prey even larger than themselves by swallowing them whole. If one's shackles are cause for discontent, perhaps it is time for some good old fashioned greed.","avail":"<ul><li><b>Covetous Gold Serpent Ring<\/b><ul><li>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>, on a corpse inside a locked cell along with <a data-e=\"siegward-of-catarina\">Siegward<\/a>. The only access is through an open window reached by jumping from the chapel's roof above the toxic swamp (<a data-e=\"old-cell-key\">Old Cell Key<\/a> required).<\/li><\/ul><\/li><li><b>Covetous Gold Serpent Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, on a corpse lying on a ledge below a broken railing, immediately after the dark room with several Irithyllian Slaves and before reaching the lake surrounding the city.<\/li><\/ul><\/li><li><b>Covetous Gold Serpent Ring+2<\/b> (NG++)<ul><li>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, in the big courtyard after defeating the <a data-e=\"the-nameless-king\">Nameless King<\/a>. A corpse on the third stairway on the right can be found holding the ring.<\/li><\/ul><\/li><li><b>Covetous Gold Serpent Ring+3<\/b> (<a data-e=\"the-ringed-city\">The Ringed City<\/a>)<ul><li>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>, in a building at the end of the great stairway. It is in the area at the top of the long ladder from the swamp guarded by multiple Hobbled Clerics, past two Ringed Knights and in the room where <a data-e=\"amnesiac-lapp\">Amnesiac Lapp<\/a> is found.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Covetous_Gold_Serpent_Ring_(Dark_Souls_III)"},{"id":"covetous-silver-serpent-ring","kind":"ring","name":"Covetous Silver Serpent Ring","page":"Covetous Silver Serpent Ring (Dark Souls III)","img":"assets/img/Covetous_Silver_Serpent_Ring__Dark_Souls_III.webp","effect":"Fallen foes yield 10% more souls.","weight":1.2,"found":"Firelink Shrine","desc":"A silver ring depicting a snake that could have been, but never was, a dragon. Fallen foes yield more souls.\nSnakes are known as creatures of great avarice, devouring prey even larger than themselves by swallowing them whole.\nIf one's shackles are cause for discontent, perhaps it is time for some old-fashioned greed.","avail":"<ul><li><b>Covetous Silver Serpent Ring<\/b><ul><li>Located on the roof of <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>. Although the <a data-e=\"tower-key\">Tower Key<\/a> can be purchased for 20,000 souls from the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> to gain access to the roof, a patient player can use a tree near the top of the shrine as a ramp to leap onto the roof. The room with the chest containing the ring is hidden behind an illusory wall reached by walking on the rafters located on top of the shrine, where Pickle Pee's lower nest lies.<\/li><\/ul><\/li><li><b>Covetous Silver Serpent Ring +1<\/b> (NG+)<ul><li>Found in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>, on a corpse lying on a wooden scaffolding, midway through the shortcut lift near the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a> bonfire.<\/li><\/ul><\/li><li><b>Covetous Silver Serpent Ring +2<\/b> (NG++)<ul><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, near the two Evangelists and the Demon. From the Evangelists, walk outside and drop down to the roof on the right. The ring is on a corpse by the chimney.<\/li><\/ul><\/li><li><b>Covetous Silver Serpent Ring +3<\/b> (<i><a data-e=\"the-ringed-city\">The Ringed City<\/a><\/i>)<ul><li>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>, soon after meeting the first two Lothric Knights. Go right, into the building where several Murkmen will spawn and you can find the <a data-e=\"murky-longstaff\">Murky Longstaff<\/a>. The wall in front of the corpse holding the staff is an illusory wall. Go through the area it hides, until the place where the <a data-e=\"great-soul-dregs\">Great Soul Dregs<\/a> is. From here, fall down to a ledge to find the ring.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>The effect of this ring stacks with other items that provide a similar effect, like the <a data-e=\"shield-of-want\">Shield of Want<\/a> and the Symbol of Avarice.<\/li><li>If the ring was not collected in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>, it can be found in the same location in the <a data-e=\"untended-graves\">Untended Graves<\/a>. However, since there is no way to open the bell tower's door and the ladder to access the roof is not present in this area, the only way to reach it is by jumping to the roof from the tree nearby.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Covetous_Silver_Serpent_Ring_(Dark_Souls_III)"},{"id":"cursebite-ring","kind":"ring","name":"Cursebite Ring","page":"Cursebite Ring (Dark Souls III)","img":"assets/img/Cursebite_Ring__Dark_Souls_III.webp","effect":"Increases curse resistance by 90.","weight":0.6,"found":"Profaned Capital","desc":"One of the bite rings native to Carim.\nIncreases curse resistance.\nThe crafting of these rings is forbidden, perhaps owing to a fear of malleable stone. Clerics, however, dabble freely in the art.","avail":"<p>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>.<\/p><p>From the <a data-e=\"profaned-capital\">Profaned Capital<\/a> bonfire, climb down the ladder and exit through a hole in the wall. The path eventually leads to a toxic swamp and the ruins of a chapel. Drop into the swamp and head inside a cavern inhabited by several Sewer Centipedes on the opposite side of the chapel. The ring can be found on a corpse within such cavern.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Cursebite_Ring_(Dark_Souls_III)"},{"id":"dark-clutch-ring","kind":"ring","name":"Dark Clutch Ring","page":"Dark Clutch Ring (Dark Souls III)","img":"assets/img/Dark_Clutch_Ring__Dark_Souls_III.webp","effect":"• Increases dark attack by 15%. • Reduces damage absorption by 10.","weight":0.8,"found":"Irithyll Dungeon","desc":"Ring depicting a hand grasping a purple stone.\nIncreases dark attack, but compromises damage absorption.\nAn old fable in Londor claims the lure of the clutch ring reaches out to the crestfallen, who might otherwise be overcome by despair.","avail":"<p>Found in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>. Dropped by the Mimic at the far-end of the sewers.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dark_Clutch_Ring_(Dark_Souls_III)"},{"id":"dark-stoneplate-ring","kind":"ring","name":"Dark Stoneplate Ring","page":"Dark Stoneplate Ring","img":"assets/img/Dark_Stoneplate_Ring.webp","effect":"Increases dark damage absorption by 13%.","weight":0.6,"found":"Irithyll of the Boreal Valley","desc":"Stoneplates are symbols of true knights, and dark purple stoneplates are granted to Undead knights.\nIncreases dark damage absorption.","avail":"<ul><li><b>Dark Stoneplate Ring<\/b><ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, on a corpse in the dark underpass adjacent to the big courtyard with several dead Giant Slaves past <a data-e=\"pontiff-sulyvahn\">Pontiff Sulyvahn<\/a>'s arena. The ring is guarded by a group of Irithyllian Slaves.<\/li><\/ul><\/li><li><b>Dark Stoneplate Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, next to the white Lothric Wyvern. From the <a data-e=\"lothric-castle\">Dragonslayer Armour<\/a> bonfire, turn back and stick to the right until an opening on the wall is found. Drop down and access a room with a Mimic and the <a data-e=\"braille-divine-tome-of-lothric\">Braille Divine Tome of Lothric<\/a>, the ring will be on a corpse outside.<\/li><\/ul><\/li><li><b>Dark Stoneplate Ring+2<\/b> (NG++)<ul><li>Found in <a data-e=\"farron-keep\">Farron Keep<\/a>. From the <a data-e=\"farron-keep\">Keep Ruins<\/a> bonfire, look behind the building beyond the three Ghrus on the bridge.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>Decreases its effectiveness the higher the player's Dark absorption becomes.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Dark_Stoneplate_Ring"},{"id":"darkmoon-ring","kind":"ring","name":"Darkmoon Ring","page":"Darkmoon Ring","img":"assets/img/Darkmoon_Ring.webp","effect":"Grants two additional attunement slots.","weight":0.8,"found":"Blade of the Darkmoon","desc":"Ring of the moon deity Gwyndolin, youngest son of Gwyn, the First Lord.\nAdds many slots for attunement.\nGwyndolin, also known as the Dark Sun, commands the Darkmoon Knights, and bestows this ring upon the best of them.","avail":"<p>Reward for reaching Rank 1 in the <a data-e=\"blade-of-the-darkmoon\">Blade of the Darkmoon<\/a> covenant. Reaching this rank requires giving ten <a data-e=\"proof-of-a-concord-kept\">Proof of a Concord Kept<\/a> to <a data-e=\"company-captain-yorshka\">Company Captain Yorshka<\/a>.<\/p>","notes":"<ul><li>If the player has attuned spells to at least all but one available slots while this ring is equipped, and attempts to remove the ring after, a warning will appear that they will lose attuned spells by doing so. Confirming the action will remove the spell(s) occupying the final two Attunement slots.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Darkmoon_Ring"},{"id":"deep-ring","kind":"ring","name":"Deep Ring","page":"Deep Ring","img":"assets/img/Deep_Ring.webp","effect":"Grants one additional attunement slot.","weight":0.5,"found":"Cathedral of the Deep","desc":"A ring bestowed upon the Deacons of the Cathedral of the Deep.\nAllows attunement of additional spells.\nIn the Cathedral slumber things most terrible, and as such, the deacons require a grand narrative, to ensure they do not falter in their duty. A philosophy, to ward away the madness beckoned by the grotesqueries at hand.","avail":"<p>Guaranteed drop from a non-hostile Deacon in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p><p>From the <a data-e=\"cathedral-of-the-deep\">Cleansing Chapel<\/a>, walk through the shortcut door on the left (having opened it previously) and take the nearby lift up the tower. The player will enter a room with a Devout of the Deep wielding a crossbow that had previously attacked the player when traversing the area below, and the ledge beyond its window outside the tower will lead further upward towards the cathedral rooftops. At the top of this ladder is a non-hostile Deacon, which can be killed to obtain the ring.<\/p>","notes":"<ul><li>If the player has attuned spells to every available slot while the ring is equipped, and attempts to remove the ring after, a warning will appear that they will lose an attuned spell by doing so. Confirming the action will remove the spell occupying the final Attunement slot.<\/li><\/ul><p>&lt;tabber&gt;Official translation= A ring bestowed upon the Deacons of the Cathedral of the Deep. Allows attunement of additional spells.<\/p><p>In the Cathedral slumber things most terrible, and as such, the deacons require a grand narrative, to ensure they do not falter in their duty. A philosophy, to ward away the madness beckoned by the grotesqueries at hand. |-|Original description (Japanese) = 深みの聖堂、その主教たちに与えられる指輪 記憶スロットを増やす<\/p><p>聖堂はおぞましいものの寝床であり 故に彼らには、大きな物語が必要だった おぞみと共に深くあり、狂わぬほどの物語が |-|Literal translation = Ring given to the bishops of the Church of the Deep. Increases memory slots.<\/p><p>The Church is a cradle of repulsive things, thus they needed a great story. A story deep like the repulsiveness enough to keep them from going insane. &lt;/tabber&gt;<\/p>","url":"https://darksouls.fandom.com/wiki/Deep_Ring"},{"id":"dragonscale-ring","kind":"ring","name":"Dragonscale Ring","page":"Dragonscale Ring","img":"assets/img/Dragonscale_Ring.webp","effect":"Reduces damage from backstabs.","weight":1.1,"found":"Consumed King's Garden","desc":"Ring of Oceiros, former king of Lothric.\nReduces damage from backstabs.\nIn his later years, Oceiros became fascinated with dragons. After going mad, he was more commonly known as the Consumed King. Many assassins were dispatched to his domain, but none returned.\nThe Consumed King ascribed his resilience to the divine protection of the dragon scale.","avail":"<p>Found in the <a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a>, on a corpse located halfway up the second lift in the area. The player needs to jump off to a ledge as the elevator moves either up or down.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonscale_Ring"},{"id":"dusk-crown-ring","kind":"ring","name":"Dusk Crown Ring","page":"Dusk Crown Ring (Dark Souls III)","img":"assets/img/Dusk_Crown_Ring__Dark_Souls_III.webp","effect":"• Reduces most spells' FP consumption by between 20-25%. • Reduces HP by 15%.","weight":0.6,"found":"Irithyll Dungeon","desc":"Leaf-colored crown ring bestowed upon the princess of Oolacile, ancient land of golden sorceries.\nReduces spell FP consumption, but also lowers HP.\nOolacile is synonymous for its lost sorceries, of which the xanthous sorcerers are dedicated scholars. This crown ring is a rare artifact of great magic heritage.","avail":"<p>Found in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>, on a corpse lying in the far-left cell of the second cell block.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dusk_Crown_Ring_(Dark_Souls_III)"},{"id":"estus-ring","kind":"ring","name":"Estus Ring","page":"Estus Ring","img":"assets/img/Estus_Ring.webp","effect":"Increases HP restored by the Estus Flask by 20%.","weight":0.8,"found":"Firelink Shrine","desc":"A green ring crafted from shards. Increases HP restored by Estus Flask.\nThis ring was entrusted to a certain Fire Keeper, but in the end she never met her champion, and the ensuing tragic farce became a favorite tale of the masses.","avail":"<p>Found at the bottom of the decrepit bell tower behind <a data-e=\"firelink-shrine\">Firelink Shrine<\/a> (<a data-e=\"tower-key\">Tower Key<\/a> required).<\/p><p>Climb up the spiraling staircase inside the first tower and enter the second one at the other end of the bridge. While facing the lift inside, drop down onto the various caskets protruding from the walls (preferably on the right side as it is safer, although on the left side the <a data-e=\"fire-keeper-set\">Fire Keeper Set<\/a> can be obtained) and make way to the bottom of the tower, where the ring can be looted from the lifeless body of an old <a data-e=\"fire-keeper\">fire keeper<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Estus_Ring"},{"id":"farron-ring","kind":"ring","name":"Farron Ring","page":"Farron Ring","img":"assets/img/Farron_Ring.webp","effect":"Reduces skill FP consumption by 25%.","weight":0.8,"found":"Firelink Shrine (gift/drop from Hawkwood)","desc":"A ring given to Undead Legion of Farron.\nReduces Skill FP consumption.\nThe Abyss Watchers, for their hunting, required a sword technique that went beyond any existing art. Wolf's blood provided just that, and this ring further extends the effect.","avail":"<ul><li>Presented to the player by <a data-e=\"hawkwood\">Hawkwood<\/a> after defeating the <a data-e=\"abyss-watchers\">Abyss Watchers<\/a>. The player may have to travel to <a data-e=\"firelink-shrine\">Firelink Shrine<\/a> and then reload the area in order to activate Hawkwood's presence.<\/li><li>Dropped by <a data-e=\"hawkwood\">Hawkwood<\/a> if the player kills him at anytime throughout the course of the game after defeating the <a data-e=\"abyss-watchers\">Abyss Watchers<\/a>. This can be achieved either at <a data-e=\"firelink-shrine\">Firelink Shrine<\/a> or after defeating him in the <a data-e=\"farron-keep\">Farron Keep<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Farron_Ring"},{"id":"fire-clutch-ring","kind":"ring","name":"Fire Clutch Ring","page":"Fire Clutch Ring (Dark Souls III)","img":"assets/img/Fire_Clutch_Ring__Dark_Souls_III.webp","effect":"• Increases fire attack by 15%. • Reduces damage absorption by 10.","weight":0.8,"found":"Undead Settlement","desc":"Ring depicting a hand grasping a red stone.\nIncreases fire attack, but compromises damage absorption.\nAn old fable in Londor claims that the lure of the clutch ring reaches out to the crestfallen, who might otherwise be overcome by despair","avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, behind the guillotine near the building where <a data-e=\"cornyx-of-the-great-swamp\">Cornyx<\/a>'s cell is located and above the <a data-e=\"undead-settlement\">Cliff Underside<\/a> bonfire.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Fire_Clutch_Ring_(Dark_Souls_III)"},{"id":"flame-stoneplate-ring","kind":"ring","name":"Flame Stoneplate Ring","page":"Flame Stoneplate Ring (Dark Souls III)","img":"assets/img/Flame_Stoneplate_Ring__Dark_Souls_III.webp","effect":"Increases fire damage absorption by 13%.","weight":0.6,"found":"Undead Settlement","desc":"Stoneplates are symbols of true knights, and red stoneplates are granted to those who valiantly face Chaos.\nIncreases fire damage absorption.","avail":"<ul><li><b>Flame Stoneplate Ring<\/b><ul><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a corpse hanging from the highest cliff and near the non-hostile Manservant. The body may fall down the cliff, forcing the player to traverse a big part of the level in order to retrieve it. If this happens, just closing and continuing the game will make it spawn lying below the tree and ready to be looted.<\/li><\/ul><\/li><li><b>Flame Stoneplate Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>. From the <a data-e=\"profaned-capital\">Profaned Capital<\/a> bonfire, climb down the ladder and exit through a hole on the wall. Proceed onward until reaching the toxic swamp and climb up the ladder on the right of the chapel's ruins. Drop down near the entrance of the room with the sleeping Monstrosity of Sin and onto a piece of roof visible below. The ring can then be looted from a body lying in a little alcove.<\/li><\/ul><\/li><li><b>Flame Stoneplate Ring+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>. From the <a data-e=\"smouldering-lake\">Demon Ruins<\/a> bonfire, descend two sets of stairs to reach a big room with two Demon Clerics. Turn right and proceed straightforward into a passage at the end. Hit the carved wall at the very end of this passage to reveal a hidden room with a Black Knight slaying a Ghru. The ring can be found inside.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>Decreases its effectiveness the higher the player's Fire absorption becomes.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Flame_Stoneplate_Ring_(Dark_Souls_III)"},{"id":"fleshbite-ring","kind":"ring","name":"Fleshbite Ring","page":"Fleshbite Ring","img":"assets/img/Fleshbite_Ring.webp","effect":"Raises poison, bleed, frost and curse resistance by 40.","weight":0.9,"found":"Grand Archives","desc":"One of the bite rings native to Carim.\nRaises poison, bleed, frost and curse resist.\nThe crafting of these rings is forbidden,\nperhaps owing to a fear of malleable stone.\nClerics, however, dabble freely in the art.","avail":"<ul><li><b>Fleshbite Ring<\/b><ul><li>Found on the sixth floor of the <a data-e=\"grand-archives\">Grand Archives<\/a>, upstairs from the area guarded by four Archive Scholars. The ring is on a corpse on the right, at the end of a hallway filled with several Clawed Curses.<\/li><\/ul><\/li><li><b>Fleshbite Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, on a roof not far from the <a data-e=\"high-wall-of-lothric\">Tower on the Wall<\/a> bonfire. Head out onto a large roof with a Pus of Man and approach the ladder at the other end. Jump on the half-gated roof in front and loot the corpse.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>The ring has no effect on Toxic resistance.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Fleshbite_Ring"},{"id":"flynns-ring","kind":"ring","name":"Flynn's Ring","page":"Flynn's Ring (Dark Souls III)","img":"assets/img/Flynn_s_Ring__Dark_Souls_III.webp","effect":"Lowering equip load increases attack power.","weight":0.9,"found":"Undead Settlement","desc":"Ring of Flynn, the eulogized thief.\nLowering equip load increases attack power.\nFlynn fought with the wind on his side, and was a hero among the weak and poor, yet even his admirers knew that it was little more than an idyllic fable.","avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. Jump off the lift that leads to the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a> while riding its upper part and onto a wooden scaffolding, then follow the only path available, fighting a Demon with <a data-e=\"siegward-of-catarina\">Siegward<\/a> along the way. The ring can be found on a corpse once reaching the rooftop of the next building.<\/p>","notes":"<ul><li>Does not grant attack power after 30 equipment weight.<\/li><li>Provides a maximum attack power increase of 15%.<ul><li>Attack power is boosted by roughly 0.5% per full point of weight under 30.<\/li><\/ul><\/li><li>The ring only boosts physical damage.<ul><li>This includes all forms of physical damage dealt by the wearer, regardless of the source. This means that items like the <a data-e=\"kukri\">Kukri<\/a>, and physical damage spells such as <a data-e=\"wrath-of-the-gods\">Wrath of the Gods<\/a> and <a data-e=\"boulder-heave\">Boulder Heave<\/a>, are also affected.<\/li><\/ul><\/li><li>The ring's weight is applied before calculation, meaning it will detract slightly from the damage boost.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Flynn's_Ring_(Dark_Souls_III)"},{"id":"great-swamp-ring","kind":"ring","name":"Great Swamp Ring","page":"Great Swamp Ring","img":"assets/img/Great_Swamp_Ring.webp","effect":"Boosts pyromancies by 12%.","weight":0.7,"found":"Road of Sacrifices (drop from Great Crab)","desc":"Ring said to be chiseled from the bone of a flame salamander by blighted Pyromancers living in the Great Swamp.\nBoosts pyromancies.\nIt is believed that salamanders are the descendants of demons, born of the Chaos Flame, from which Pyromancy is also said to have originated.","avail":"<ul><li>Starting equipment of the Pyromancer class.<\/li><li>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>. Dropped by the Great Crab pacing around a patch of deep water near the fortress. That crab is near the tree with two corpses of supposed Pyromancers, as they have the <a data-e=\"conjurator-set\">Conjurator Set<\/a> and <a data-e=\"great-swamp-pyromancy-tome\">Great Swamp Pyromancy Tome<\/a> with them.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Swamp_Ring"},{"id":"havels-ring","kind":"ring","name":"Havel's Ring","page":"Havel's Ring (Dark Souls III)","img":"assets/img/Havel_s_Ring__Dark_Souls_III.webp","effect":"Increases maximum equip load by 15%.","weight":1.5,"found":"Transposed from the Soul of a Stray Demon.","desc":"A ring for warriors keen on heavy accoutrements. Increases maximum equip load.\nThis ring was named after Havel the Rock, the battlefield compatriot of Gwyn, the First Lord.\nThe art of war has been a constant since ages past, and those who follow in Havel's footsteps are no fewer now than in his own day.","avail":"<ul><li><b>Havel's Ring<\/b><ul><li>Obtained by transposing the <a data-e=\"soul-of-a-stray-demon\">Soul of a Stray Demon<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/li><\/ul><\/li><li><b>Havel's Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, on a corpse lying immediately to the left after exiting the room where the big mob of Man Serpents were hiding, on the path that leads to the altar that bestows the <a data-e=\"twinkling-dragon-torso-stone\">Twinkling Dragon Torso Stone<\/a>.<\/li><\/ul><\/li><li><b>Havel's Ring+2<\/b> (NG++)<ul><li>Found in <a data-e=\"anor-londo\">Anor Londo<\/a>, in the Prison Tower where Captain Yorshka resides. Drop down the tower and the ring will be on the third corpse, after the <a data-e=\"painting-guardians-curved-sword\">Painting Guardian's Curved Sword<\/a> and the <a data-e=\"painting-guardian-set\">Painting Guardian Set<\/a>.<\/li><\/ul><\/li><li><b>Havel's Ring+3<\/b> (<i><a data-e=\"the-ringed-city\">The Ringed City<\/a><\/i> DLC).<ul><li>After defeating Silver Knight Ledo, drop down from the stone path that led you to the broken tower. The ring is on a ledge after falling down a few times.<\/li><\/ul><\/li><\/ul>","notes":"","from_soul":[{"soul":"soul-of-a-stray-demon","cost":"5,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Havel's_Ring_(Dark_Souls_III)"},{"id":"hawk-ring","kind":"ring","name":"Hawk Ring","page":"Hawk Ring (Dark Souls III)","img":"assets/img/Hawk_Ring__Dark_Souls_III.webp","effect":"Extends firing range of arrows.","weight":0.7,"found":"Undead Settlement","desc":"Ring associated with Hawkeye Gough, one of the Four Knights of Gwyn, the First Lord.\nExtends the range of arrows.\nIn his later years, the giant Gough was blinded, but this did not prevent him from striking down a calamitous dragon with his Greatbow.","avail":"<ul><li>Dropped by the <a data-e=\"giant-archer-of-the-undead-settlement\">giant archer<\/a> at the top of the highest tower in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><li>Alternatively, if the player collects all <a data-e=\"young-white-branch\">Young White Branches<\/a> found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a> and the <a data-e=\"farron-keep\">Farron Keep<\/a>, the giant will die and the ring can then be looted from his body at the top of the aforementioned tower.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Hawk_Ring_(Dark_Souls_III)"},{"id":"hornet-ring","kind":"ring","name":"Hornet Ring","page":"Hornet Ring (Dark Souls III)","img":"assets/img/Hornet_Ring__Dark_Souls_III.webp","effect":"Boosts critical attacks","weight":1.1,"found":"Untended Graves","desc":"Ring associated with the Lord's Blade Ciaran, one of the Four Knights of Gwyn, the First Lord.\nBoosts critical attacks.\nThe masked Ciaran was the only woman to serve in Gwyn's Four Knights, and her curved sword granted a swift death to any and all enemies of the throne.","avail":"<p>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/p><p>From the <a data-e=\"firelink-shrine\">shrine<\/a>'s entrance, follow the path on the right. The ring can be found near the same grave where <a data-e=\"hawkwood\">Hawkwood<\/a> usually goes to pray in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>. It is guarded by a <a data-e=\"black-knight-greataxe\">greataxe<\/a>-wielding Black Knight and will appear only after the <a data-e=\"abyss-watchers\">Abyss Watchers<\/a> have been defeated.<\/p>","notes":"<ul><li>Like its <i>Dark Souls<\/i> predecessor, equipping this ring causes the wearer to perform the <i>Demon's Souls<\/i> critical animations against human opponents, which causes the attacks to be reduced differently by their flat defenses.<\/li><li>Different animations will manipulate the foe's positioning differently. For example, a riposte while wearing the Hornet Ring will make the victim fall near the place where they got riposted. Meanwhile a backstab with the Hornet Ring will make the victim roll once after the backstab, causing them to fall further away. This makes fighting near cliffs a solid strategy for players who tend to go for backstabs.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Hornet_Ring_(Dark_Souls_III)"},{"id":"horsehoof-ring","kind":"ring","name":"Horsehoof Ring","page":"Horsehoof Ring","img":"assets/img/Horsehoof_Ring.webp","effect":"Enemies lose 30% more stamina when kicked.","weight":0.6,"found":"Firelink Shrine (sold or dropped by Patches)","desc":"An old ring with a seal depicting a horse's hoof. Boosts kick effect.\nUnbreakable Patches adored this ring and the feeling that it gave him when he kicked his marks into the depths of treacherous traps, but suffered no shortage of ridicule from his associates for relying so heavily on the tired old trick.\nBut who is the sorrier? The horse who knows only to kick, or the fool who approaches the old beast without thought?.","avail":"<p>Found in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>. Sold by <a data-e=\"unbreakable-patches\">Unbreakable Patches<\/a> for 500 souls or dropped by him if killed.<\/p><p>For the ring to appear in Patches' inventory, <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> must be present in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a> at the same time as him. If Patches mentions Greirat when talked to, then the ring will be added to his selling wares.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Horsehoof_Ring"},{"id":"hunters-ring","kind":"ring","name":"Hunter's Ring","page":"Hunter's Ring","img":"assets/img/Hunter_s_Ring.webp","effect":"Increases dexterity by 5.","weight":0.8,"found":"Grand Archives","desc":"Ring engraved with a portrait of a hunter.\nIncreases dexterity.\nThe hunters serve Lothric on the fringes and in the shadows. For generations, rulers of Lothric have relied especially upon the Black Hand hunters to punish enemies in ways that the king's Three Pillars cannot.","avail":"<p>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>, on a corpse lying at the top of the highest tower of the library's main dome, guarded by three Gertrude's Knights.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Hunter's_Ring"},{"id":"knight-slayers-ring","kind":"ring","name":"Knight Slayer's Ring","page":"Knight Slayer's Ring","img":"assets/img/Knight_Slayer_s_Ring.webp","effect":"Enemies lose 20% more stamina when guarding attacks.","weight":0.9,"found":"Catacombs of Carthus (dropped by Tsorig)","desc":"Ring of the savage Tsorig, more commonly known as the Knight Slayer.\nEnemies lose more stamina when guarding attacks.\nLong ago, Tsorig engaged the guardians of an ancient city in a bloody confrontation, and returned with their rings as his prize, still frozen on their dismembered fingers.","avail":"<p><a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a><\/p><ul><li>Dropped by dark spirit Knight Slayer Tsorig. From the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a> bonfire, head downstairs and enter the first doorway on the right, where an <a data-e=\"ember\">Ember<\/a> can be found at the end. Tsorig will invade as the player makes their way out.<\/li><\/ul><p><a data-e=\"smouldering-lake\">Smouldering Lake<\/a><\/p><ul><li>If the player did not defeat Tsorig in the <a data-e=\"catacombs-of-carthus\">catacombs<\/a>, he will drop the ring in this location. He awaits hidden near the lowermost staircase of the level, which leads to a lava pool.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Knight_Slayer's_Ring"},{"id":"knights-ring","kind":"ring","name":"Knight's Ring","page":"Knight's Ring","img":"assets/img/Knight_s_Ring.webp","effect":"Increases strength by 5.","weight":0.8,"found":"Lothric Castle","desc":"Ring engraved with a portrait of a knight.\nIncreases strength.\nIn Lothric, the Knight has long been considered one of the Three Pillars of the king's rule, and were thus allowed to rear dragons.","avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>.<\/p><p>From the <a data-e=\"lothric-castle\">Dragonslayer Armour<\/a> bonfire head back toward the shortcut lift. Instead of riding it, climb the ladder found around the corner to reach the rooftops and make way to the right and into another room, then climb down the ladder in there. The ring can be found on a corpse at the bottom.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Knight's_Ring"},{"id":"leo-ring","kind":"ring","name":"Leo Ring","page":"Leo Ring (Dark Souls III)","img":"assets/img/Leo_Ring__Dark_Souls_III.webp","effect":"Strengthens thrust weapon counter attacks by 15%.","weight":0.5,"found":"Irithyll of the Boreal Valley","desc":"Ring associated with Dragon Slayer Ornstein, one of the Four Knights of Gwyn, the First Lord.\nStrengthens thrust weapon counter attacks.\nOrnstein was the first knight of the sun's eldest born, and his cross spear is said to have pierced scales made of stone.","avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, in a chest on the second floor of the gallery guarded by three Silver Knights, after exiting the drainage ditch with several Sewer Centipedes.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Leo_Ring_(Dark_Souls_III)"},{"id":"life-ring","kind":"ring","name":"Life Ring","page":"Life Ring (Dark Souls III)","img":"assets/img/Life_Ring__Dark_Souls_III.webp","effect":"Raises maximum HP by 7%.","weight":0.3,"found":"• Burial gift • Firelink Shrine (sold by the Shrine Handmaid)","desc":"A generations-old ring set with a small red jewel.\nRaises maximum HP.\nRings have unique powers, and their discovery will do much to ease a wearisome journey.","avail":"<ul><li><b>Life Ring<\/b><ul><li>Can be chosen as a burial gift at the beginning of the game.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 1,500 souls once she has been given the <a data-e=\"dreamchasers-ashes\">Dreamchaser's Ashes<\/a>.<\/li><\/ul><\/li><li><b>Life Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on the ledge where <a data-e=\"siegward-of-catarina\">Siegward<\/a> is met the second time after dropping off the upper part of the lift that leads to the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>. It can be looted from a corpse lying on the second archway, to the right of Siegward.<\/li><\/ul><\/li><li><b>Life Ring+2<\/b> (NG+)<ul><li>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>. From the <a data-e=\"lothric-castle\">Dragon Barracks<\/a>, cross the bridge and enter the building on the right. Climb up the ladder and exit through the archway on the left. Once outside, head around the corner to the right and from the spot with the corpse hanging on the ledge, drop down to another ledge with a corpse holding the ring.<\/li><\/ul><\/li><li><b>Life Ring+3<\/b> (NG++)<ul><li>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>, behind Prince Lothric's throne in the ruins of <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Life_Ring_(Dark_Souls_III)"},{"id":"lightning-clutch-ring","kind":"ring","name":"Lightning Clutch Ring","page":"Lightning Clutch Ring (Dark Souls III)","img":"assets/img/Lightning_Clutch_Ring__Dark_Souls_III.webp","effect":"• Increases lightning attack by 15%. • Reduces damage absorption by 10.","weight":0.8,"found":"Archdragon Peak","desc":"Ring depicting a hand grasping a yellow stone.\nIncreases lightning attack, but compromises damage absorption.\nAn old fable in Londor claims that the lure of the clutch ring reaches out to the crestfallen, who might otherwise be overcome by despair.","avail":"<p>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, on a corpse located in an alcove to the left of the gate that leads to the <a data-e=\"ancient-wyvern\">Ancient Wyvern<\/a> boss battle and past a Man Serpent.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Lightning_Clutch_Ring_(Dark_Souls_III)"},{"id":"lingering-dragoncrest-ring","kind":"ring","name":"Lingering Dragoncrest Ring","page":"Lingering Dragoncrest Ring (Dark Souls III)","img":"assets/img/Lingering_Dragoncrest_Ring__Dark_Souls_III.webp","effect":"Extends length of spell effects by 30%.","weight":0.5,"found":"Farron Keep (dropped by Great Crab)","desc":"A special ring given to those who are deemed fit to undertake the journey of discovery in Vinheim, home of sorcery.\nExtends length of spell effect.\nApropos to the Dragon School, the seal depicts an everlasting dragon. A lingering dragon symbolizes the true nature of the consummate sorcerer.","avail":"<ul><li><b>Lingering Dragoncrest Ring<\/b><ul><li>Found in the <a data-e=\"farron-keep\">Farron Keep<\/a>, dropped by the Great Crab dwelling on the murky water to the left of the <a data-e=\"farron-keep\">Keep Ruins<\/a> bonfire and the main gate. If the player befriended the <a data-e=\"giant-archer-of-the-undead-settlement\">giant archer<\/a>, he will lend a hand in defeating it in this place.<\/li><\/ul><\/li><li><b>Lingering Dragoncrest Ring +1<\/b> (NG+)<ul><li>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, on a corpse lying near the first Great Crab in the <a data-e=\"road-of-sacrifices\">Crucifixion Woods<\/a>.<\/li><\/ul><\/li><li><b>Lingering Dragoncrest Ring +2<\/b> (NG++)<ul><li>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>, on a corpse lying halfway up the tower with the three Gertrude's Knights at the library's main dome.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>Does not affect the duration of effects granted by using skills.<\/li><li>The ring reduces the decay rate of the buff while it is worn. This means that the ring must be constantly equipped in order to benefit from the increased duration.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Lingering_Dragoncrest_Ring_(Dark_Souls_III)"},{"id":"lloyds-shield-ring","kind":"ring","name":"Lloyd's Shield Ring","page":"Lloyd's Shield Ring","img":"assets/img/Lloyd_s_Shield_Ring.webp","effect":"Boosts damage absorption by 25% when HP is full.","weight":0.9,"found":"Firelink Shrine (sold by the Shrine Handmaid)","desc":"Ring given to knights of the Way of White. Depicts Allfather Lloyd's Shield of Caste.\nBoosts damage absorption when HP is full.\nMuch time has passed since the worship of Lloyd was common in the Way of White. The clerics of Carim had always strongly asserted that Lloyd was a derivative fraud, and that the Allfather title was self-proclaimed.","avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 2,500 souls once she has been given the <a data-e=\"paladins-ashes\">Paladin's Ashes<\/a>.<\/p>","notes":"<ul><li>The ring's effect triggers about at 98% of the player's HP, allowing them to take some damage through a shield and still gain the damage absorption boost.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Lloyd's_Shield_Ring"},{"id":"lloyds-sword-ring","kind":"ring","name":"Lloyd's Sword Ring","page":"Lloyd's Sword Ring","img":"assets/img/Lloyd_s_Sword_Ring.webp","effect":"Boosts attack power by 12.5% when HP is full.","weight":0.9,"found":"Cathedral of the Deep","desc":"Ring given to knights of the Way of White. Depicts Allfather Lloyd's Sword of Law.\nBoosts attack power when HP is full.\nMuch time has passed since the worship of Lloyd was common in the Way of White. The clerics of Carim had always strongly asserted that Lloyd was a derivative fraud, and that the Allfather title was self-proclaimed.","avail":"<p>Found on a corpse in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. The body can be found lying on the central wall of the &quot;U&quot;-shaped corridor on the second floor, where the first Giant Slave attacks.<\/p>","notes":"<ul><li>The ring's effect triggers at about 98% of the player's HP, allowing them to take a small amount of damage and still gain the attack boost.<\/li><li>The ring does not affect the damage of consumable items, such as <a data-e=\"throwing-knife\">throwing knives<\/a> and <a data-e=\"firebomb\">firebombs<\/a><\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Lloyd's_Sword_Ring"},{"id":"magic-clutch-ring","kind":"ring","name":"Magic Clutch Ring","page":"Magic Clutch Ring","img":"assets/img/Magic_Clutch_Ring.webp","effect":"• Increases magic attack by 15%. • Reduces damage absorption by 10.","weight":0.8,"found":"Irithyll of the Boreal Valley","desc":"Ring depicting a hand grasping a blue stone.\nIncreases magic attack, but compromises damage absorption.\nAn old fable in Londor claims that the lure of the clutch ring reaches out to the crestfallen, who might otherwise be overcome by despair.","avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p><p>From <a data-e=\"irithyll-of-the-boreal-valley\">Central Irithyll<\/a>, proceed through the level until reaching a cathedral at the end of the main street. The ring can be uncovered behind an illusory wall located to the right of the altar holding the <a data-e=\"ring-of-the-suns-first-born\">Ring of the Sun's First Born<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Magic_Clutch_Ring"},{"id":"magic-stoneplate-ring","kind":"ring","name":"Magic Stoneplate Ring","page":"Magic Stoneplate Ring","img":"assets/img/Magic_Stoneplate_Ring.webp","effect":"Increases Magic damage absorption by 13%.","weight":0.6,"found":"Consumed King's Garden (dropped by a Consumed King's Knight)","desc":"Stoneplates are symbols of true knights, and blue stoneplates are granted to royal palace guards.\nIncreases magic damage absorption.","avail":"<ul><li><b>Magic Stoneplate Ring<\/b><ul><li>Found in the <a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a>. Guaranteed drop from the Consumed King's Knight guarding <a data-e=\"oceiros-the-consumed-king\">King Oceiros<\/a>'s lair.<\/li><\/ul><\/li><li><b>Magic Stoneplate Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"farron-keep\">Farron Keep<\/a>. From the <a data-e=\"farron-keep\">Farron Keep<\/a> bonfire, head right to an area with deep water and several Basilisks. The ring is on a corpse lying behind a big tree on the left.<\/li><\/ul><\/li><li><b>Magic Stoneplate Ring+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>. From the <a data-e=\"profaned-capital\">Profaned Capital<\/a> bonfire, climb down the interior ladder, exit through the hole on the wall and turn right. The ring will be toward the end of this path.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Magic_Stoneplate_Ring"},{"id":"mornes-ring","kind":"ring","name":"Morne's Ring","page":"Morne's Ring","img":"assets/img/Morne_s_Ring.webp","effect":"Boosts miracles by 12%.","weight":0.7,"found":"Road of Sacrifices","desc":"A malformed ring given to knights of Carim.\nBoosts miracles.\nMorne served the goddess Caitha and later became an apostle of the Archbishop. They labored together to provide comfort to the suffering.","avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>.<\/p><p>From the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a> bonfire, drop from the ledge behind the first Corvian Storyteller. Continue onward until reaching a bridge with another Storyteller at the end and several Corvians scattered about. Drop by the right side before crossing and to a small ledge below, then follow the narrow path until reaching a cave guarded by two Festering Starved Hounds. The ring can be found on a corpse inside, along with another one that holds the <a data-e=\"braille-divine-tome-of-carim\">Braille Divine Tome of Carim<\/a>.<\/p>","notes":"<ul><li>Does not boost miracles that provide buffs or healing.<\/li><li>Stacks with other miracle-boosting items such as the <a data-e=\"ring-of-the-suns-first-born\">Ring of the Sun's First Born<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Morne's_Ring"},{"id":"obscuring-ring","kind":"ring","name":"Obscuring Ring","page":"Obscuring Ring","img":"assets/img/Obscuring_Ring.webp","effect":"Hides the presence of the wearer when far away.","weight":0.9,"found":"Cathedral of the Deep - gift from Rosaria","desc":"Ring bestowed upon the Fingers of Rosaria, invaders who seek tongues for their goddess.\nHides the presence of the wearer when far away.\nIt is said that Rosaria, the mother of rebirth, was robbed of her tongue by her firstborn, and has been waiting for their return ever since.","avail":"<p>Obtained by reaching Rank 1 in the <a data-e=\"rosarias-fingers\">Rosaria's Fingers<\/a> covenant by offering 10 <a data-e=\"pale-tongue\">Pale Tongues<\/a>.<\/p>","notes":"<ul><li>There is no visual cue that informs the wearer of this ring having taken effect.<\/li><li>Only works against human players. AI-controlled enemies will still detect the player normally.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Obscuring_Ring"},{"id":"poisonbite-ring","kind":"ring","name":"Poisonbite Ring","page":"Poisonbite Ring (Dark Souls III)","img":"assets/img/Poisonbite_Ring__Dark_Souls_III.webp","effect":"Increases poison resistance by 90.","weight":0.6,"found":"Cathedral of the Deep","desc":"One of the bite rings native to Carim.\nIncreases poison resistance.\nThe crafting of these rings is forbidden, perhaps owing to a fear of malleable stone.\nClerics, however, dabble freely in the art.","avail":"<ul><li><b>Poisonbite Ring<\/b><ul><li>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. From the <a data-e=\"cathedral-of-the-deep\">Cleansing Chapel<\/a>, head in the graveyard's direction but deviate through a narrow path on the right. Make way around a small waterway with three Corpse Grubs until reaching a sleeping Ravenous Crystal Lizard. Enter the narrow passage on its right to find another Corpse Grub guarding the ring.<\/li><\/ul><\/li><li><b>Poisonbite Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. From the <a data-e=\"undead-settlement\">Dilapidated Bridge<\/a>, head through the cemetery until reaching the house at the far end, then head to the left and uphill until reaching the smaller house with the <a data-e=\"cleric-set\">Cleric Set<\/a>. The ring can be found on a corpse lying behind the well on the left.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>This ring does not increase Toxic resistance.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Poisonbite_Ring_(Dark_Souls_III)"},{"id":"pontiffs-left-eye","kind":"ring","name":"Pontiff's Left Eye","page":"Pontiff's Left Eye","img":"assets/img/Pontiff_s_Left_Eye.webp","effect":"Recovers 30 HP with successive attacks.","weight":0.9,"found":"Transposed from the Soul of Boreal Valley Vordt.","desc":"Bewitched ring that Pontiff Sulyvahn bestowed upon his knights.\nRecovers HP with successive attacks.\nKnights who peer into the black orb are lured into battles of death, transformed into frenzied beasts. No wonder the Pontiff only provides these rings to those dispatched to foreign lands.","avail":"<p>Obtained by transposing the <a data-e=\"soul-of-boreal-valley-vordt\">Soul of Boreal Valley Vordt<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>The healing effect does not occur only with successive attacks; instead, each weapon type has a determined quota that must be satisfied in order for the ring to start healing the player.<\/li><\/ul>","from_soul":[{"soul":"soul-of-boreal-valley-vordt","cost":null}],"url":"https://darksouls.fandom.com/wiki/Pontiff's_Left_Eye"},{"id":"pontiffs-right-eye","kind":"ring","name":"Pontiff's Right Eye","page":"Pontiff's Right Eye","img":"assets/img/Pontiff_s_Right_Eye.webp","effect":"Boosts attacks to a maximum of +10%, as long as attacking persists.","weight":1.4,"found":"Irithyll of the Boreal Valley","desc":"Bewitched ring that Pontiff Sulyvahn bestowed upon his knights.\nBoosts attacks, as long as attacking persists.\nKnights who peer into the black orb are lured into battles of death, transformed into frenzied beasts. No wonder the Pontiff only provides these rings to those dispatched to foreign lands.","avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>. Guaranteed drop from the Sulyvahn's Beast that ambushes on the bridge to Central Irithyll.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Pontiff's_Right_Eye"},{"id":"priestess-ring","kind":"ring","name":"Priestess Ring","page":"Priestess Ring","img":"assets/img/Priestess_Ring.webp","effect":"Increases faith","weight":0.6,"found":"Dark Firelink Shrine (sold by the Shrine Handmaid)","desc":"A ring engraved with a portrait of the High Priestess.\nIncreases faith.\nIn Lothric, the High Priestess has long been considered one of the Three Pillars of the king's rule. The High Priestess also served as the prince's wet nurse.","avail":"<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> in <a data-e=\"untended-graves\">Dark Firelink Shrine<\/a> for 1,000 souls.<ul><li>Dropped by the Shrine Handmaid if she is killed in Dark Firelink Shrine.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Priestess_Ring"},{"id":"prisoners-chain","kind":"ring","name":"Prisoner's Chain","page":"Prisoner's Chain","img":"assets/img/Prisoner_s_Chain.webp","effect":"Gain vigor, endurance, and vitality by 5, but take 4% extra damage.","weight":0.8,"found":"Transpose the Soul of Champion Gundyr.","desc":"Portion of a steel chain used to restrain Gundyr. Gain vigor, endurance, and vitality, but take extra damage.\nA prisoner is one who has staked everything on a belief, a proclivity most apparent in the greatest of champions.","avail":"<p>Obtained by transposing the <a data-e=\"soul-of-champion-gundyr\">Soul of Champion Gundyr<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>Prior to the App 1.13 Regulation 1.33 patch, the Prisoner's Chain would reduce absorption by 10%, rather than 4%.<\/li><\/ul>","from_soul":[{"soul":"soul-of-champion-gundyr","cost":null}],"url":"https://darksouls.fandom.com/wiki/Prisoner's_Chain"},{"id":"red-tearstone-ring","kind":"ring","name":"Red Tearstone Ring","page":"Red Tearstone Ring (Dark Souls III)","img":"assets/img/Red_Tearstone_Ring__Dark_Souls_III.webp","effect":"Temporarily boosts attack by 20% when HP is below 20%.","weight":1.4,"found":"Lothric Castle","desc":"A ring set with a large rare tearstone jewel.\nTemporarily boosts attack when HP is low.\nThis stone is said to be a tear of mourning of the goddess Caitha, and of course, tears are always more beautiful near death.","avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, just before the <a data-e=\"dragonslayer-armour\">Dragonslayer Armour<\/a>. From the <a data-e=\"lothric-castle\">Dragon Barracks<\/a>, head across the bridge and through the entrance of the castle, heading upstairs and to the left. Continue forward and outside, where an entrance to the right should be followed, into a small chapel with the shortcut lift to the <a data-e=\"grand-archives\">Grand Archives<\/a>. Head to the left and outside onto a balcony where a corpse can be found holding the ring.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Red_Tearstone_Ring_(Dark_Souls_III)"},{"id":"reversal-ring","kind":"ring","name":"Reversal Ring","page":"Reversal Ring","img":"assets/img/Reversal_Ring.webp","effect":"Causes males to perform female actions, and vice-versa.","weight":0.5,"found":"Irithyll of the Boreal Valley","desc":"A divine ring granted to the Darkmoon Gwyndolin in his youth.\nCauses males to perform female actions, and vice-versa.\nGwyndolin was raised like a daughter through the aura of the moon, and was said to behave like a sullen brooding goddess.","avail":"<p>Found at the very end of <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a> in the Darkmoon Tomb, to the right of Gwyn's coffin. The area is concealed behind an illusory statue of Lord Gwyn. If <a data-e=\"yuria-of-londor\">Yuria<\/a>'s questline has progressed far enough, the tomb will already be open.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Reversal_Ring"},{"id":"ring-of-favor","kind":"ring","name":"Ring of Favor","page":"Ring of Favor","img":"assets/img/Ring_of_Favor.webp","effect":"Increases max HP by 3%, stamina by 9%, and maximum equip load by 5%.","weight":1.5,"found":"Irithyll of the Boreal Valley","desc":"A ring symbolizing the favor of the Goddess Fina, whose \"fateful beauty\" is mentioned in legend.\nTrue to the fickle nature of Fina's favor, her ring increases max HP, stamina, and maximum equip load.","avail":"<ul><li><b>Ring of Favor<\/b><ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>. Dropped by one of the two Sulyvahn's Beasts lurking in the <a data-e=\"irithyll-of-the-boreal-valley\">Water Reserve<\/a>.<\/li><\/ul><\/li><li><b>Ring of Favor+1<\/b> (NG+)<ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, along the rafters above <a data-e=\"pontiff-sulyvahn\">Pontiff Sulyvahn<\/a>'s boss room.<\/li><\/ul><\/li><li><b>Ring of Favor+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. On the rooftops leading to the rafters, the ring can be found in an alcove to the left, guarded by a Large Devout of the Deep.<\/li><\/ul><\/li><li><b>Ring of Favor+3<\/b><ul><li>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>. In the swamp past the <a data-e=\"the-dreg-heap\">Earthen Peak Ruins<\/a> bonfire. Located up a large root straight ahead from where you enter the swamp.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Ring_of_Favor"},{"id":"ring-of-sacrifice","kind":"ring","name":"Ring of Sacrifice","page":"Ring of Sacrifice (Dark Souls III)","img":"assets/img/Ring_of_Sacrifice__Dark_Souls_III.webp","effect":"Wearer will lose no souls upon death, but the ring itself breaks afterward.","weight":1,"found":"Various locations","desc":"This mystical ring was created in a sacrificial rite of Velka, the Goddess of Sin.\nIts wearer will lose nothing upon death, but the ring itself breaks.\nA sacrifice is only worth as much as the life it spares.","avail":"<ul><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>One can be obtained by trading <a data-e=\"lorettas-bone\">Loretta's Bone<\/a> with Pickle Pee (only once per playthrough).<\/li><li>Three are sold by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a> for 5,000 souls each.<\/li><li>Any rings that weren't bought from Yuria before her death will be sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 5,000 souls each once she is given <a data-e=\"yurias-ashes\">Yuria's Ashes<\/a>.<\/li><\/ul><\/li><li><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><ul><li>One is found on a corpse past the <a data-e=\"high-wall-of-lothric\">Tower on the Wall<\/a> bonfire, near the Winged Knight. You have to mount the small, flat-topped building (reached by a set of stairs on the right, past the courtyard with the knight, then turning right again and up another set of stairs to reach the rooftop) and jump to an awning which holds the corpse and the ring.<\/li><\/ul><\/li><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>One is found on a corpse halfway down a series of ledges on the side of the building to the left of the Exile Watchdogs<\/li><\/ul><\/li><li><a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a><ul><li>One is found below the quay, on the rightmost corner of the lake surrounding the city, between the <a data-e=\"irithyll-of-the-boreal-valley\">Church of Yorshka<\/a> and the <a data-e=\"irithyll-of-the-boreal-valley\">Distant Manor<\/a>.<\/li><\/ul><\/li><li><a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a><ul><li>One is found on a corpse tucked in the corner to the right immediately upon exiting the building containing the main elevator.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>The Ring of Sacrifice is removed from the player's inventory after being used for revival.<\/li><li>The Host of Embers status is lost after revival.<\/li><li>Dying as a phantom with the ring equipped will activate it, providing no benefit but still breaking it. As such, one should make sure to swap to other rings whenever summoned.<\/li><li>Existing bloodstains will remain intact if the player dies while wearing the Ring of Sacrifice.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Ring_of_Sacrifice_(Dark_Souls_III)"},{"id":"ring-of-steel-protection","kind":"ring","name":"Ring of Steel Protection","page":"Ring of Steel Protection (Dark Souls III)","img":"assets/img/Ring_of_Steel_Protection__Dark_Souls_III.webp","effect":"Increases physical damage absorption by 10%.","weight":0.6,"found":"Archdragon Peak","desc":"Ring of the Knight King of ancient legend. Increases physical damage absorption.\nThe Knight King was said to be lined with steel on the inside, such that even the talons of mighty dragons did him little harm.","avail":"<ul><li><b>Ring of Steel Protection<\/b><ul><li>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, at the ruins where the <a data-e=\"ancient-wyvern\">Ancient Wyvern<\/a> initially appears. Complete the boss fight and return to the initial area beyond the main gate. At the main fork in front of the bell, turn right into an area with three lootable corpses and approach the ledge on the right. Walk around the railing and onto a narrow path that leads to a corpse holding the ring.<\/li><\/ul><\/li><li><b>Ring of Steel Protection +1<\/b> (NG+)<ul><li>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>, on a corpse lying to the right of the tower behind the <a data-e=\"firelink-shrine\">shrine<\/a>.<\/li><\/ul><\/li><li><b>Ring of Steel Protection +2<\/b> (NG++)<ul><li>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>, on top of a small pillar below the left side of the first stone bridge.<\/li><\/ul><\/li><li><b>Ring of Steel Protection +3<\/b><ul><li>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>. After falling into the ruins of the <a data-e=\"grand-archives\">Grand Archives<\/a> and encountering the first Angel, the ring can be found at the end of a wooden scaffolding that is guarded by the Angel. Killing the Pilgrim Pupa and then doubling back will allow it to be picked up safely.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Ring_of_Steel_Protection_(Dark_Souls_III)"},{"id":"ring-of-the-evil-eye","kind":"ring","name":"Ring of the Evil Eye","page":"Ring of the Evil Eye (Dark Souls III)","img":"assets/img/Ring_of_the_Evil_Eye__Dark_Souls_III.webp","effect":"Absorb 30 HP from each defeated foe.","weight":1,"found":"Catacombs of Carthus (gift from Anri)","desc":"This ring captured the foul spirit of an evil eye, a creature that ravaged Astora.\nAbsorb HP from each defeated foe.\nThe horrid spirit nearly destroyed Astora, but was eventually defeated by \"the sword of one most noble.\"","avail":"<ul><li><b>Ring of the Evil Eye<\/b><ul><li>Given by <a data-e=\"anri-of-astora\">Anri of Astora<\/a> within the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>, if the player tells them the whereabouts of <a data-e=\"horace-the-hushed\">Horace the Hushed<\/a>.<\/li><li>Alternatively, Anri will give the ring to the player in the <a data-e=\"irithyll-of-the-boreal-valley\">Church of Yorshka<\/a> if they are not told of Horace's location.<\/li><\/ul><\/li><li><b>Ring of the Evil Eye+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a> behind the giant concealed statue, right before the <a data-e=\"deacons-of-the-deep\">Deacons of the Deep<\/a>.<\/li><\/ul><\/li><li><b>Ring of the Evil Eye+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, in a corner behind some barrels in the room where the <a data-e=\"cell-key\">Cell Key<\/a> and the first <a data-e=\"estus-shard\">Estus Shard<\/a> are found.<\/li><\/ul><\/li><li><b>Ring of the Evil Eye+3<\/b> (<a data-e=\"the-ringed-city\">The Ringed City<\/a>)<ul><li>Guaranteed drop from a Mimic found within the <a data-e=\"the-ringed-city\">Shared Grave<\/a> area, at the bottom of the stairwell where the Moaning Knight is fought.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Ring_of_the_Evil_Eye_(Dark_Souls_III)"},{"id":"ring-of-the-suns-first-born","kind":"ring","name":"Ring of the Sun's First Born","page":"Ring of the Sun's First Born","img":"assets/img/Ring_of_the_Sun_s_First_Born.webp","effect":"Boosts miracles by 20%.","weight":1,"found":"Irithyll of the Boreal Valley","desc":"Ring of the Sun's first born, who inherited the light of Gwyn, the first lord.\nGreatly boosts miracles.\nThe Sun's first born was once a god of war, until he was stripped of his stature as punishment for his foolishness. No wonder his very name has slipped from the annals of history.","avail":"<p>Found at <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p><p>From the <a data-e=\"irithyll-of-the-boreal-valley\">Pontiff Sulyvahn<\/a> bonfire, head back out toward the railing and fall straight onto the altar below.<\/p>","notes":"<ul><li>Does not boost miracles that provide buffs or healing.<\/li><li>Stacks with other miracle-boosting items such as the Crown of Dusk and <a data-e=\"mornes-ring\">Morne's Ring<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Ring_of_the_Sun's_First_Born"},{"id":"sage-ring","kind":"ring","name":"Sage Ring","page":"Sage Ring","img":"assets/img/Sage_Ring.webp","effect":"Shortens spell casting time by increasing virtual Dexterity by 30.","weight":0.7,"found":"Road of Sacrifices","desc":"A ring given to Farron's Undead Legion by one of the preacher twins, known more commonly as the Crystal Sages.\nShortens spell casting time.\nThe sorcerers of Farron's Abyss Watchers were known to be lonesome warriors who would only rely upon more pragmatic spells.","avail":"<ul><li><b>Sage Ring<\/b><ul><li>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, in a secluded room guarded by a Lycanthrope to the left of the staircase that gives access to the right entrance of the keep. The room can also be entered by a hole on the floor located between the first and second pillars to the right after entering the final area before the <a data-e=\"crystal-sage\">Crystal Sage<\/a>.<\/li><\/ul><\/li><li><b>Sage Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>, on a corpse lying along the rafters after dropping down from Gertrude's bird cage, on the east-southern corner.<\/li><\/ul><\/li><li><b>Sage Ring+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a>. While riding the lift into the garden, jump off midway onto the platform leading to the <a data-e=\"estus-shard\">Estus Shard<\/a>. The ring will be on a part of the broken stairs opposite the shard that must be jumped to.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Sage_Ring"},{"id":"saints-ring","kind":"ring","name":"Saint's Ring","page":"Saint's Ring","img":"assets/img/Saint_s_Ring.webp","effect":"Grants one extra attunement slot.","weight":0.5,"found":"Firelink Shrine (sold by Irina)","desc":"A ring bestowed upon a Carim Saint.\nAllows attunement of additional spells.\nIn Carim, the saints give voice to the ancient tales. They memorize countless cumbersome sacred books and read them in sonorous tones, a function for which they are widely renowned.","avail":"<p><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><\/p><ul><li>Sold by <a data-e=\"irina-of-carim\">Irina of Carim<\/a> for 300 souls.<\/li><\/ul>","notes":"<ul><li>If the player has attuned spells to every available slot while the ring is equipped, and attempts to remove the ring after, a warning will appear that they will lose an attuned spell by doing so. Confirming the action will remove the spell occupying the final Attunement slot.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Saint's_Ring"},{"id":"scholar-ring","kind":"ring","name":"Scholar Ring","page":"Scholar Ring","img":"assets/img/Scholar_Ring.webp","effect":"Increases Intelligence by 5.","weight":0.6,"found":"Grand Archives","desc":"Ring engraved with a portrait of a scholar.\nIncreases intelligence.\nIn Lothric, the Scholar has long been considered one of the Three Pillars of the king's rule, and is therefore master of the Grand Archives.","avail":"<p>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p><p>Pull the lever found to the right of the wooden bridge on the third floor of the library, facing the bridge from the red-eyed Lothric Knight. A pair of bookshelves will move out of the way, giving access to a corpse sitting on a chair holding the ring.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Scholar_Ring"},{"id":"silvercat-ring","kind":"ring","name":"Silvercat Ring","page":"Silvercat Ring (Dark Souls III)","img":"assets/img/Silvercat_Ring__Dark_Souls_III.webp","effect":"Prevents damage from falling.","weight":0.6,"found":"Firelink Shrine (gift from Sirris)","desc":"Silver ring depicting a leaping feline.\nPrevents damage from falling.\nIn the Age of Gods, or possibly just following it, an old cat was said to speak a human tongue, with the voice of an old woman, and the form of a fanciful immortal.","avail":"<p>Obtained as a gift from <a data-e=\"sirris-of-the-sunless-realms\">Sirris<\/a> in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a> after helping her defeat Creighton in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p><p>To perform this task, the player must look for Sirris's summon sign near the first half of the bridge that connects the <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a> bonfire to <a data-e=\"irithyll-of-the-boreal-valley\">Central Irithyll<\/a> and answer her call. If successful, the next time they visit <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>, she will greet and thank them for their help, bestowing the ring as a reward.<\/p>","notes":"<ul><li>Joining <a data-e=\"rosarias-fingers\">Rosaria's Fingers<\/a> anytime before completing the first phase of <a data-e=\"sirris-of-the-sunless-realms\">Sirris<\/a>'s questline will deprive the player from obtaining the ring in that playthrough, as Sirris will only appear one more time to say goodbye and then disappear from the game.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Silvercat_Ring_(Dark_Souls_III)"},{"id":"skull-ring","kind":"ring","name":"Skull Ring","page":"Skull Ring","img":"assets/img/Skull_Ring.webp","effect":"Wearer is easier to be detected by enemies.","weight":0.6,"found":"Firelink Shrine (dropped by Ludleth)","desc":"One of Courland's transposed wonders. Derived from the soul of a Soulfeeder.\nEasier to be detected by enemies.\nThe Soulfeeder was a beast that insatiably absorbed souls to feed its own power. Even after its accursed corpse was burned, it is said that the pungent stench of souls left the air permanently stained.","avail":"<ul><li>Dropped by <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/li><li>If the player has placed all four <a data-e=\"cinders-of-a-lord\">cinders<\/a> on their respective thrones, Ludleth will die in the following cutscene and the ring can then be retrieved from his throne.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Skull_Ring"},{"id":"slumbering-dragoncrest-ring","kind":"ring","name":"Slumbering Dragoncrest Ring","page":"Slumbering Dragoncrest Ring (Dark Souls III)","img":"assets/img/Slumbering_Dragoncrest_Ring__Dark_Souls_III.webp","effect":"Silences all sounds made by its wearer.","weight":0.7,"found":"Firelink Shrine (gift from Orbeck)","desc":"Ring of a clandestine guild of sorcerers based in Vinheim, home of sorcery.\nMasks the sound of its wearer.\nThe Dragon School held effective sovereignty over Vinheim, with a great many adept assassins at its disposal.","avail":"<p>Gift from <a data-e=\"orbeck-of-vinheim\">Orbeck of Vinheim<\/a> after purchasing the following sorceries:<\/p><ul><li><a data-e=\"aural-decoy\">Aural Decoy<\/a> (2,000 souls)<\/li><li><a data-e=\"farron-flashsword\">Farron Flashsword<\/a> (3,000 souls)<\/li><li><a data-e=\"pestilent-mist\">Pestilent Mist<\/a> (1,000 souls)<\/li><li><a data-e=\"spook\">Spook<\/a> (2,000 souls)<\/li><\/ul>","notes":"<ul><li>After the player has purchased the required sorceries, choosing the &quot;Talk&quot; option will yield the ring along with the &quot;Silent Ally&quot; gesture.<ul><li>If the player has not yet satisfied the requirements to obtain the <a data-e=\"young-dragon-ring\">Young Dragon Ring<\/a>, they will receive it at that moment instead. Selecting the &quot;Talk&quot; option a second time will yield the Slumbering Dragoncrest Ring along with the gesture.<\/li><\/ul><\/li><li>A glitch may occur where enemies will still be able to detect the player's presence from behind even when the ring is equipped. Exiting and continuing the game usually fixes this.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Slumbering_Dragoncrest_Ring_(Dark_Souls_III)"},{"id":"speckled-stoneplate-ring","kind":"ring","name":"Speckled Stoneplate Ring","page":"Speckled Stoneplate Ring (Dark Souls III)","img":"assets/img/Speckled_Stoneplate_Ring__Dark_Souls_III.webp","effect":"Increases magic, fire, lightning, and dark damage absorption by 5%.","weight":0.9,"found":"Smouldering Lake","desc":"Stoneplates are symbols of true knights, and speckled stoneplates are granted to those who face an endless journey.\nSlightly increases magic, fire, lightning, and dark damage absorption.","avail":"<ul><li><b>Speckled Stoneplate Ring<\/b><ul><li>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>, behind a brick wall. The wall is located on the far-left side of the initial cavern (if looking toward the ballista and opposite to the <a data-e=\"old-demon-king\">Old Demon King<\/a> boss room) and can only be destroyed by making one of the arrows to hit it.<\/li><\/ul><\/li><li><b>Speckled Stoneplate Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>, on a corpse near the Ravenous Crystal Lizard.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Speckled_Stoneplate_Ring_(Dark_Souls_III)"},{"id":"sun-princess-ring","kind":"ring","name":"Sun Princess Ring","page":"Sun Princess Ring","img":"assets/img/Sun_Princess_Ring.webp","effect":"Restores 2 HP per second.","weight":0.6,"found":"Anor Londo","desc":"Ring associated with Gwynevere, princess of sunlight and eldest daughter of Gwyn, the First Lord.\nThe ring is vaguely warm, like a beam of sunlight, and gradually restores HP.\nGwynevere left her home with a great many other deities, and became a wife and a mother, raising several heavenly children.","avail":"<p>Found in <a data-e=\"anor-londo\">Anor Londo<\/a>. From the <a data-e=\"anor-londo\">Aldrich, Devourer of Gods<\/a> bonfire, ride up any of the two elevators and enter the Chamber of the Princess to find the ring.<\/p>","notes":"<ul><li>Stacks with other spells and items that restore health over time, such as <a data-e=\"replenishment\">Replenishment<\/a> and the <a data-e=\"ethereal-oak-shield\">Ethereal Oak Shield<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Sun_Princess_Ring"},{"id":"thunder-stoneplate-ring","kind":"ring","name":"Thunder Stoneplate Ring","page":"Thunder Stoneplate Ring (Dark Souls III)","img":"assets/img/Thunder_Stoneplate_Ring__Dark_Souls_III.webp","effect":"Increases lightning damage absorption by 13%.","weight":0.6,"found":"Archdragon Peak","desc":"Stoneplates are symbols of true knights, and yellow stoneplates are granted to those who would become dragons.\nIncreases lightning damage absorption.","avail":"<ul><li><b>Thunder Stoneplate Ring<\/b><ul><li>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>. From the <a data-e=\"archdragon-peak\">Dragon-Kin Mausoleum<\/a>, proceed onward through the level along an open side path guarded by several Man Serpents. Once at the other end, look for a wooden scaffolding with another Man Serpent below and drop to it. Climb up the ladder around the corner to find the ring at the top.<\/li><\/ul><\/li><li><b>Thunder Stoneplate Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>, in the same alley filled with urns where the <a data-e=\"carthus-milkring\">Carthus Milkring<\/a> is found.<\/li><\/ul><\/li><li><b>Thunder Stoneplate Ring+2<\/b> (NG++)<ul><li>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>. From the <a data-e=\"lothric-castle\">Dragonslayer Armour<\/a> bonfire, backtrack and head left into a room with the shortcut lift for the <a data-e=\"grand-archives\">Grand Archives<\/a>. Exit through an archway on the left to reach a balcony with the <a data-e=\"red-tearstone-ring\">Red Tearstone Ring<\/a>. Look for a crumbled part on the railing of this balcony and drop down to the roof below. The ring can be found on the right, at the far end of this roof.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Thunder_Stoneplate_Ring_(Dark_Souls_III)"},{"id":"untrue-dark-ring","kind":"ring","name":"Untrue Dark Ring","page":"Untrue Dark Ring","img":"assets/img/Untrue_Dark_Ring.webp","effect":"Retain human appearance while Hollow.","weight":0.7,"found":"Firelink Shrine (sold by Yuria)","desc":"One of the illusory rings worn by the Hollows of Londor.\nRetain human appearance while Hollow.\nThe Hollows of Londor are wretchedly aged, fraught with deceit, and dubiously secretive. It is no wonder that they are deeply detested.","avail":"<p>Sold by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a> for 5,000 souls.<\/p><p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> if given <a data-e=\"yurias-ashes\">Yuria's Ashes<\/a> and the ring was not bought previously.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Untrue_Dark_Ring"},{"id":"untrue-white-ring","kind":"ring","name":"Untrue White Ring","page":"Untrue White Ring","img":"assets/img/Untrue_White_Ring.webp","effect":"Take the appearance of a phantom.","weight":0.7,"found":"Firelink Shrine (sold by Yuria of Londor)","desc":"One of the illusory rings worn by the Hollows of Londor.\nTake the appearance of a phantom.\nThe Hollows of Londor are wretchedly aged, fraught with deceit, and dubiously secretive.\nIt is no wonder that they are deeply detested.","avail":"<p>Sold by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a> for 5,000 souls.<\/p>","notes":"<ul><li>Will hide the Hollowing status of the wearer, alongside giving them the white phantom aura.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Untrue_White_Ring"},{"id":"witchs-ring","kind":"ring","name":"Witch's Ring","page":"Witch's Ring","img":"assets/img/Witch_s_Ring.webp","effect":"Boosts pyromancies by 20%.","weight":1,"found":"Catacombs of Carthus","desc":"The Witch of Izalith and her daughters, scorched by the Flame of Chaos, taught humans the art of pyromancy and offered them this ring.\nGreatly boosts pyromancies.\nEvery pyromancer is familiar with the parable that tells of the witches espousing the need to fear the flame, and teaching the art of pyromancy to men in hopes that they might learn to control it.","avail":"<p>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a> just before reaching the <a data-e=\"catacombs-of-carthus\">Abandoned Tomb<\/a>, on a corpse lying at the end of a small corridor past the area with the Demon and several Skeletons. The body holds both the ring and the Old Sage's Blindfold.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Witch's_Ring"},{"id":"wolf-ring","kind":"ring","name":"Wolf Ring","page":"Wolf Ring (Dark Souls III)","img":"assets/img/Wolf_Ring__Dark_Souls_III.webp","effect":"Increases poise by 4.","weight":0.5,"found":"Farron Keep (reward)","desc":"Ring associated with Abysswalker Artorias, one of the Four Knights of Gwyn, the First Lord.\nIncrease Poise.\nArtorias had an unbendable will of steel, and was unmatched with a greatsword.","avail":"<ul><li><b>Wolf Ring<\/b><ul><li>Awarded to the player for reaching Rank 2 in the <a data-e=\"watchdogs-of-farron\">Watchdogs of Farron<\/a>. Achieving this rank requires offering 30 <a data-e=\"wolfs-blood-swordgrass\">Wolf's Blood Swordgrass<\/a> to the Old Wolf of Farron.<\/li><\/ul><\/li><li><b>Wolf Ring+1<\/b> (NG+)<ul><li>Found in <a data-e=\"farron-keep\">Farron Keep<\/a>, hidden behind a wall around the <a data-e=\"farron-keep\">Keep Ruins<\/a> bonfire.<\/li><\/ul><\/li><li><b>Wolf Ring+2<\/b> (NG++)<ul><li>Found in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>, on a corpse lying immediately to the left after opening the door from the <a data-e=\"cemetery-of-ash\">Iudex Gundyr<\/a> bonfire.<\/li><\/ul><\/li><li><b>Wolf Ring+3<\/b><ul><li>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>. After reaching the great stairway that leads down to the Ringed City Streets, cross over the first bridge that overlooks the stairway. After defeating a sword-wielding Ringed Knight and continuing on the path, the Seeker of the Spurned will invade. Defeat him and he will drop the ring.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Wolf_Ring_(Dark_Souls_III)"},{"id":"wood-grain-ring","kind":"ring","name":"Wood Grain Ring","page":"Wood Grain Ring","img":"assets/img/Wood_Grain_Ring.webp","effect":"Slows equipment degradation by 20%.","weight":0.5,"found":"Firelink Shrine (sold by the Shrine Handmaid)","desc":"This special ring crafted in an Eastern land is made of metal, but with a wood grain crest on its surface. Slows equipment degradation.\nWielders of swords originating in the same region follow a practice of inscribing special words on the blades of their swords, and are naturally drawn to this ring.","avail":"<ul><li><b>Wood Grain Ring<\/b><ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 3,000 souls once she has been given the <a data-e=\"easterners-ashes\">Easterner's Ashes<\/a>.<\/li><\/ul><\/li><li><b>Wood Grain Ring+1<\/b> (NG+)<ul><li>Found in the <a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a>. When taking the lift to enter the garden, the ring is on a corpse lying behind the lift at the bottom.<\/li><\/ul><\/li><li><b>Wood Grain Ring+2<\/b> (NG++)<ul><li>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>. From the <a data-e=\"irithyll-of-the-boreal-valley\">Distant Manor<\/a>, head back into the drainage ditch and into the gallery guarded by three Silver Knights. The ring can be found on a corpse lying to the right after exiting the gallery.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>Degradation reduction only affects durability damage incurred by being damaged by attacks (in the case of armor) and by attacking entities (in the case of weapons). This means that it is incapable of reducing degradation from <a data-e=\"acid-surge\">Acid Surge<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Wood_Grain_Ring"},{"id":"young-dragon-ring","kind":"ring","name":"Young Dragon Ring","page":"Young Dragon Ring","img":"assets/img/Young_Dragon_Ring.webp","effect":"Boosts sorceries by 12%.","weight":0.7,"found":"Firelink Shrine (gift from Orbeck)","desc":"Ring given in Vinheim, home of sorcery, when newly ordained as a sorcerer.\nBoosts sorceries.\nApropos to the Dragon School, the seal depicts an everlasting dragon. A young dragon presages the great length of the journey to mastery.","avail":"<ul><li>Starting equipment of the Sorcerer class.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Gift from <a data-e=\"orbeck-of-vinheim\">Orbeck of Vinheim<\/a> after meeting the following criteria:<ol><li>Play any class other than a Sorcerer.<\/li><li>Purchase at least four sorceries from him.<\/li><li>Give him at least one scroll.<\/li><\/ol><\/li><\/ul><\/li><\/ul>","notes":"<ul><li>In order to obtain the Master of Rings achievement/trophy with the Sorcerer as the starting class, this ring needs to be dropped on the ground and picked back up again.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Young_Dragon_Ring"}]);
